package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.SamlIdpEntityIdVO;

class SamlIdpEntityIdValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of saml idp entity id of tenant login provider")
  void test_saml_idp_entity_id_value_holder_assign_plain_value() {
    Object holder = new Object();
    SamlIdpEntityIdValueHolder<Object> value = new SamlIdpEntityIdValueHolder<>(holder);
    Assertions.assertSame(holder, value.samlIdpEntityId("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getSamlIdpEntityIdValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getSamlIdpEntityId().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.samlIdpEntityIdNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getSamlIdpEntityIdValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getSamlIdpEntityId().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of saml idp entity id of tenant login provider")
  void test_saml_idp_entity_id_value_holder_assign_value_object() {
    Object holder = new Object();
    SamlIdpEntityIdValueHolder<Object> value = new SamlIdpEntityIdValueHolder<>(holder);
    SamlIdpEntityIdVO vo = SamlIdpEntityIdVO.from("one");
    Assertions.assertFalse(value.getSamlIdpEntityIdValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.samlIdpEntityId(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSamlIdpEntityIdValue().orElseThrow());
    Assertions.assertSame(holder, value.samlIdpEntityId(Optional.empty()));
    Assertions.assertFalse(value.getSamlIdpEntityIdValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.samlIdpEntityId(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSamlIdpEntityIdValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of saml idp entity id of tenant login provider against the original")
  void test_saml_idp_entity_id_value_holder_read() {
    Object holder = new Object();
    SamlIdpEntityIdValueHolder<Object> value = new SamlIdpEntityIdValueHolder<>(holder);
    SamlIdpEntityIdVO vo = SamlIdpEntityIdVO.from("one");
    SamlIdpEntityIdVO other = SamlIdpEntityIdVO.from("one");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getSamlIdpEntityIdValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSamlIdpEntityId(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readSamlIdpEntityId(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.samlIdpEntityId(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSamlIdpEntityId(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSamlIdpEntityId(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of saml idp entity id of tenant login provider")
  void test_saml_idp_entity_id_value_holder_unset() {
    Object holder = new Object();
    SamlIdpEntityIdValueHolder<Object> value = new SamlIdpEntityIdValueHolder<>(holder);
    SamlIdpEntityIdVO vo = SamlIdpEntityIdVO.from("one");
    value.samlIdpEntityId(vo);
    Assertions.assertSame(holder, value.unsetSamlIdpEntityIdIfMatches("samlIdpEntityId_other"));
    Assertions.assertTrue(value.getSamlIdpEntityIdValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSamlIdpEntityIdIfMatches("samlIdpEntityId"));
    Assertions.assertFalse(value.getSamlIdpEntityIdValue().isPresent(),
        "The field name must clear the value");
    value.samlIdpEntityId(vo);
    Assertions.assertSame(holder, value.unsetSamlIdpEntityId());
    Assertions.assertFalse(value.getSamlIdpEntityIdValue().isPresent(),
        "Unset must clear the value");
  }
}
